def _create_fn(name, args, body, *, globals=None, locals=None, return_type=MISSING):
    if locals is None:
        locals = {}
    return_annotation = ''
    if return_type is not MISSING:
        locals['__dataclass_return_type__'] = return_type
        return_annotation = '->__dataclass_return_type__'
    args = ','.join(args)
    body = '\n'.join((f'  {b}' for b in body))
    txt = f' def {name}({args}){return_annotation}:\n{body}'
    local_vars = ', '.join(locals.keys())
    txt = f'def __create_fn__({local_vars}):\n{txt}\n return {name}'
    ns = {}
    exec(txt, globals, ns)
    return ns['__create_fn__'](**locals)

def _process_class(cls, init, repr, eq, order, unsafe_hash, frozen, match_args, kw_only, slots, weakref_slot):
    fields = {}
    if cls.__module__ in sys.modules:
        globals = sys.modules[cls.__module__].__dict__
    else:
        globals = {}
    setattr(cls, _PARAMS, _DataclassParams(init, repr, eq, order, unsafe_hash, frozen, match_args, kw_only, slots, weakref_slot))
    any_frozen_base = False
    has_dataclass_bases = False
    for b in cls.__mro__[-1:0:-1]:
        base_fields = getattr(b, _FIELDS, None)
        if base_fields is not None:
            has_dataclass_bases = True
            for f in base_fields.values():
                fields[f.name] = f
            if getattr(b, _PARAMS).frozen:
                any_frozen_base = True
    cls_annotations = inspect.get_annotations(cls)
    cls_fields = []
    KW_ONLY_seen = False
    dataclasses = sys.modules[__name__]
    for name, type in cls_annotations.items():
        if _is_kw_only(type, dataclasses) or (isinstance(type, str) and _is_type(type, cls, dataclasses, dataclasses.KW_ONLY, _is_kw_only)):
            if KW_ONLY_seen:
                raise TypeError(f'{name!r} is KW_ONLY, but KW_ONLY has already been specified')
            KW_ONLY_seen = True
            kw_only = True
        else:
            cls_fields.append(_get_field(cls, name, type, kw_only))
    for f in cls_fields:
        fields[f.name] = f
        if isinstance(getattr(cls, f.name, None), Field):
            if f.default is MISSING:
                delattr(cls, f.name)
            else:
                setattr(cls, f.name, f.default)
    for name, value in cls.__dict__.items():
        if isinstance(value, Field) and (not name in cls_annotations):
            raise TypeError(f'{name!r} is a field but has no type annotation')
    if has_dataclass_bases:
        if any_frozen_base and (not frozen):
            raise TypeError('cannot inherit non-frozen dataclass from a frozen one')
        if not any_frozen_base and frozen:
            raise TypeError('cannot inherit frozen dataclass from a non-frozen one')
    setattr(cls, _FIELDS, fields)
    class_hash = cls.__dict__.get('__hash__', MISSING)
    has_explicit_hash = not (class_hash is MISSING or (class_hash is None and '__eq__' in cls.__dict__))
    if order and (not eq):
        raise ValueError('eq must be true if order is true')
    all_init_fields = [f for f in fields.values() if f._field_type in (_FIELD, _FIELD_INITVAR)]
    std_init_fields, kw_only_init_fields = _fields_in_init_order(all_init_fields)
    if init:
        has_post_init = hasattr(cls, _POST_INIT_NAME)
        _set_new_attribute(cls, '__init__', _init_fn(all_init_fields, std_init_fields, kw_only_init_fields, frozen, has_post_init, '__dataclass_self__' if 'self' in fields else 'self', globals, slots))
    field_list = [f for f in fields.values() if f._field_type is _FIELD]
    if repr:
        flds = [f for f in field_list if f.repr]
        _set_new_attribute(cls, '__repr__', _repr_fn(flds, globals))
    if eq:
        flds = [f for f in field_list if f.compare]
        self_tuple = _tuple_str('self', flds)
        other_tuple = _tuple_str('other', flds)
        _set_new_attribute(cls, '__eq__', _cmp_fn('__eq__', '==', self_tuple, other_tuple, globals=globals))
    if order:
        flds = [f for f in field_list if f.compare]
        self_tuple = _tuple_str('self', flds)
        other_tuple = _tuple_str('other', flds)
        for name, op in [('__lt__', '<'), ('__le__', '<='), ('__gt__', '>'), ('__ge__', '>=')]:
            if _set_new_attribute(cls, name, _cmp_fn(name, op, self_tuple, other_tuple, globals=globals)):
                raise TypeError(f'Cannot overwrite attribute {name} in class {cls.__name__}. Consider using functools.total_ordering')
    if frozen:
        for fn in _frozen_get_del_attr(cls, field_list, globals):
            if _set_new_attribute(cls, fn.__name__, fn):
                raise TypeError(f'Cannot overwrite attribute {fn.__name__} in class {cls.__name__}')
    hash_action = _hash_action[bool(unsafe_hash), bool(eq), bool(frozen), has_explicit_hash]
    if hash_action:
        cls.__hash__ = hash_action(cls, field_list, globals)
    if not getattr(cls, '__doc__'):
        try:
            text_sig = str(inspect.signature(cls)).replace(' -> None', '')
        except (TypeError, ValueError):
            text_sig = ''
        cls.__doc__ = cls.__name__ + text_sig
    if match_args:
        _set_new_attribute(cls, '__match_args__', tuple((f.name for f in std_init_fields)))
    if weakref_slot and (not slots):
        raise TypeError('weakref_slot is True but slots is False')
    if slots:
        cls = _add_slots(cls, frozen, weakref_slot)
    abc.update_abstractmethods(cls)
    return cls

def read_table(source, *, columns=None, use_threads=True, schema=None, use_pandas_metadata=False, read_dictionary=None, binary_type=None, list_type=None, memory_map=False, buffer_size=0, partitioning='hive', filesystem=None, filters=None, ignore_prefixes=None, pre_buffer=True, coerce_int96_timestamp_unit=None, decryption_properties=None, thrift_string_size_limit=None, thrift_container_size_limit=None, page_checksum_verification=False, arrow_extensions_enabled=True):
    try:
        dataset = ParquetDataset(source, schema=schema, filesystem=filesystem, partitioning=partitioning, memory_map=memory_map, read_dictionary=read_dictionary, binary_type=binary_type, list_type=list_type, buffer_size=buffer_size, filters=filters, ignore_prefixes=ignore_prefixes, pre_buffer=pre_buffer, coerce_int96_timestamp_unit=coerce_int96_timestamp_unit, decryption_properties=decryption_properties, thrift_string_size_limit=thrift_string_size_limit, thrift_container_size_limit=thrift_container_size_limit, page_checksum_verification=page_checksum_verification, arrow_extensions_enabled=arrow_extensions_enabled)
    except ImportError:
        if filters is not None:
            raise ValueError("the 'filters' keyword is not supported when the pyarrow.dataset module is not available")
        if partitioning != 'hive':
            raise ValueError("the 'partitioning' keyword is not supported when the pyarrow.dataset module is not available")
        if schema is not None:
            raise ValueError("the 'schema' argument is not supported when the pyarrow.dataset module is not available")
        if isinstance(source, list):
            raise ValueError("the 'source' argument cannot be a list of files when the pyarrow.dataset module is not available")
        filesystem, path = _resolve_filesystem_and_path(source, filesystem)
        if filesystem is not None:
            if not filesystem.get_file_info(path).is_file:
                raise ValueError("the 'source' argument should be an existing parquet file and not a directory when the pyarrow.dataset module is not available")
            source = filesystem.open_input_file(path)
        dataset = ParquetFile(source, read_dictionary=read_dictionary, binary_type=binary_type, list_type=list_type, memory_map=memory_map, buffer_size=buffer_size, pre_buffer=pre_buffer, coerce_int96_timestamp_unit=coerce_int96_timestamp_unit, decryption_properties=decryption_properties, thrift_string_size_limit=thrift_string_size_limit, thrift_container_size_limit=thrift_container_size_limit, page_checksum_verification=page_checksum_verification)
    return dataset.read(columns=columns, use_threads=use_threads, use_pandas_metadata=use_pandas_metadata)

def __init__(self, path_or_paths, filesystem=None, schema=None, *, filters=None, read_dictionary=None, binary_type=None, list_type=None, memory_map=False, buffer_size=None, partitioning='hive', ignore_prefixes=None, pre_buffer=True, coerce_int96_timestamp_unit=None, decryption_properties=None, thrift_string_size_limit=None, thrift_container_size_limit=None, page_checksum_verification=False, arrow_extensions_enabled=True):
    import pyarrow.dataset as ds
    read_options = {'pre_buffer': pre_buffer, 'coerce_int96_timestamp_unit': coerce_int96_timestamp_unit, 'thrift_string_size_limit': thrift_string_size_limit, 'thrift_container_size_limit': thrift_container_size_limit, 'page_checksum_verification': page_checksum_verification, 'arrow_extensions_enabled': arrow_extensions_enabled, 'binary_type': binary_type, 'list_type': list_type}
    if buffer_size:
        read_options.update(use_buffered_stream=True, buffer_size=buffer_size)
    if read_dictionary is not None:
        read_options.update(dictionary_columns=read_dictionary)
    if decryption_properties is not None:
        read_options.update(decryption_properties=decryption_properties)
    self._filter_expression = None
    if filters is not None:
        self._filter_expression = filters_to_expression(filters)
    if filesystem is not None:
        filesystem = _ensure_filesystem(filesystem, use_mmap=memory_map)
    elif filesystem is None and memory_map:
        filesystem = LocalFileSystem(use_mmap=memory_map)
    if hasattr(path_or_paths, '__fspath__') and filesystem is not None and (not isinstance(filesystem, LocalFileSystem)):
        raise TypeError(f'Path-like objects with __fspath__ must only be used with local file systems, not {type(filesystem)}')
    single_file = None
    self._base_dir = None
    if not isinstance(path_or_paths, list):
        if _is_path_like(path_or_paths):
            filesystem, path_or_paths = _resolve_filesystem_and_path(path_or_paths, filesystem, memory_map=memory_map)
            finfo = filesystem.get_file_info(path_or_paths)
            if finfo.is_file:
                single_file = path_or_paths
            if finfo.type == FileType.Directory:
                self._base_dir = path_or_paths
        else:
            single_file = path_or_paths
    parquet_format = ds.ParquetFileFormat(**read_options)
    if single_file is not None:
        fragment = parquet_format.make_fragment(single_file, filesystem)
        self._dataset = ds.FileSystemDataset([fragment], schema=schema or fragment.physical_schema, format=parquet_format, filesystem=fragment.filesystem)
        return
    if partitioning == 'hive':
        partitioning = ds.HivePartitioning.discover(infer_dictionary=True)
    self._dataset = ds.dataset(path_or_paths, filesystem=filesystem, schema=schema, format=parquet_format, partitioning=partitioning, ignore_prefixes=ignore_prefixes)

def read(self, columns=None, use_threads=True, use_pandas_metadata=False):
    metadata = self.schema.metadata or {}
    if use_pandas_metadata:
        if b'pandas' not in metadata:
            common_metadata = self._get_common_pandas_metadata()
            if common_metadata:
                metadata = common_metadata
    if columns is not None and use_pandas_metadata:
        if metadata and b'pandas' in metadata:
            index_columns = [col for col in _get_pandas_index_columns(metadata) if not isinstance(col, dict)]
            columns = list(columns) + list(set(index_columns) - set(columns))
    table = self._dataset.to_table(columns=columns, filter=self._filter_expression, use_threads=use_threads)
    if use_pandas_metadata:
        if metadata and b'pandas' in metadata:
            new_metadata = table.schema.metadata or {}
            new_metadata.update({b'pandas': metadata[b'pandas']})
            table = table.replace_schema_metadata(new_metadata)
    return table

def _ensure_filesystem(filesystem, *, use_mmap=False):
    if isinstance(filesystem, FileSystem):
        return filesystem
    elif isinstance(filesystem, str):
        if use_mmap:
            raise ValueError('Specifying to use memory mapping not supported for filesystem specified as an URI string')
        fs, path = FileSystem.from_uri(filesystem)
        prefix = fs.normalize_path(path)
        if prefix:
            prefix_info = fs.get_file_info([prefix])[0]
            if prefix_info.type != FileType.Directory:
                raise ValueError(f'The path component of the filesystem URI must point to a directory but it has a type: `{prefix_info.type.name}`. The path component is `{prefix_info.path}` and the given filesystem URI is `{filesystem}`')
            fs = SubTreeFileSystem(prefix, fs)
        return fs
    else:
        try:
            import fsspec
        except ImportError:
            pass
        else:
            if isinstance(filesystem, fsspec.AbstractFileSystem):
                if type(filesystem).__name__ == 'LocalFileSystem':
                    return LocalFileSystem(use_mmap=use_mmap)
                return PyFileSystem(FSSpecHandler(filesystem))
        raise TypeError(f'Unrecognized filesystem: {type(filesystem)}. `filesystem` argument must be a FileSystem instance or a valid file system URI')

def _resolve_filesystem_and_path(path, filesystem=None, *, memory_map=False):
    if not _is_path_like(path):
        if filesystem is not None:
            raise ValueError("'filesystem' passed but the specified path is file-like, so there is nothing to open with 'filesystem'.")
        return (filesystem, path)
    if filesystem is not None:
        filesystem = _ensure_filesystem(filesystem, use_mmap=memory_map)
        if isinstance(filesystem, LocalFileSystem):
            path = _stringify_path(path)
        elif not isinstance(path, str):
            raise TypeError('Expected string path; path-like objects are only allowed with a local filesystem')
        path = filesystem.normalize_path(path)
        return (filesystem, path)
    path = _stringify_path(path)
    filesystem = LocalFileSystem(use_mmap=memory_map)
    try:
        file_info = filesystem.get_file_info(path)
    except ValueError:
        file_info = None
        exists_locally = False
    else:
        exists_locally = file_info.type != FileType.NotFound
    if not exists_locally:
        try:
            filesystem, path = FileSystem.from_uri(path)
        except ValueError as e:
            msg = str(e)
            if 'empty scheme' in msg or 'Cannot parse URI' in msg:
                pass
            else:
                raise e
    else:
        path = filesystem.normalize_path(path)
    return (filesystem, path)
